"""AI attribution: this whole file was generated by Claude (Anthropic) in Claude Code, following
design decisions made by the author. See ATTRIBUTION.md for details.

Evidence-reliability experiment, step 0 (written 2026-11-23, after the test; post hoc and descriptive, no criterion):
does the frozen main system know when it hears worse? Reads only the existing outputs of the registered noise analysis
(scripts/p1v4_noise_final.py: data/p1v4/runs/final/<split>/noise/<level>/<system>.json) and the rows and front-end
detections of the level folders; runs no system and changes no frozen file.

Questions: the main body (subset None, excluded units left out) of R-hear and S-move, every question with a gold
answer, at the levels dclean, dnoise5 and dnoise10.
Systems (local, with scores): main system (2d), old head (L1), T, L2, L3, 2b ears, 2c ears, each at its frozen
threshold from the freeze record. The API rivals have answers only, so they have no confidence and are left out.
Confidence of a decision: the score's distance from the threshold, scaled to [0, 1]: (s - th) / (1 - th) above the
threshold, (th - s) / th below it.
Per system, level and part:
  accuracy per question; mean confidence (all, right, wrong); AUROC of confidence for right vs wrong decisions; share
  of decisions with confidence >= 0.5 ("confident"); error rate among them ("confident errors"); accuracy on the 80%
  and 50% most confident questions.
R-hear label-right subset: questions whose ring-class label (a phone, doorbell or knock detection >= 0.5 in the 8 s
window before the decision) matches the truth (a real event of those classes in the window) at both dclean and
dnoise10, so the label stays right while the sound gets worse; accuracy and mean confidence of each system at both
levels. The transcripts also get worse with the noise; the old head, whose decisions follow the text, is the check.
Reading, fixed before the run: the main system "knows it hears worse" if, from dclean to dnoise10, its share of
confident decisions falls, its confident-error rate does not rise and its AUROC stays about the same; it "does not
know" if its confident-error rate rises (it is wrong with high confidence more often).
Check: group accuracy of the main system and the old head per part and level reproduces results/main_v04/noise_<split>
.json; the script stops on a mismatch.
usage (repo root): P1V4_FINAL_RUN=1 .venv-gpu/Scripts/python.exe -X utf8 scripts/p1v4_step0_confidence.py test
Output: results/main_v04/step0_confidence_<split>.json
"""
import json
import os
import sys

import numpy as np
from scipy.stats import rankdata

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import p1v4_context as C  # noqa: E402
import p1v4_data as D  # noqa: E402
import p1v4_noise_final as NF  # noqa: E402
import p1v4_score as S  # noqa: E402

LEVELS = ("dclean", "dnoise5", "dnoise10")
FILES = {"2d": "2d", "L1": "L1", "T": "T", "L2": "L2", "L3": "L3", "2b ears": "2b_ears", "2c ears": "2c_ears"}
RING = ("phone", "doorbell", "knock")
HIGH = 0.5


def thresholds(st):
    th = {"2d": (st["main"]["th_s"], st["main"]["th_r"]),
          "2b ears": (st["readouts"]["2b ears"]["th_s"], st["readouts"]["2b ears"]["th_r"]),
          "2c ears": (st["readouts"]["2c ears"]["th_s"], st["readouts"]["2c ears"]["th_r"])}
    for n in ("L1", "L2", "L3", "T"):
        th[n] = (st["local"][n]["th_s"], st["local"][n]["th_r"])
    return th


def confidence(s, th):
    if s >= th:
        return (s - th) / (1 - th) if th < 1 else 1.0
    return (th - s) / th if th > 0 else 1.0


def auroc(conf, right):
    conf, right = np.asarray(conf, float), np.asarray(right, bool)
    n1, n0 = int(right.sum()), int((~right).sum())
    if n1 == 0 or n0 == 0:
        return None
    r = rankdata(conf)
    return float((r[right].sum() - n1 * (n1 + 1) / 2) / (n1 * n0))


def summary(conf, right):
    conf, right = np.asarray(conf, float), np.asarray(right, bool)
    order = np.argsort(-conf, kind="stable")
    hi = conf >= HIGH

    def top(frac):
        k = max(1, int(round(frac * len(conf))))
        return float(right[order[:k]].mean())
    return {"n": int(len(conf)), "accuracy": float(right.mean()), "mean_conf": float(conf.mean()),
            "mean_conf_right": float(conf[right].mean()) if right.any() else None,
            "mean_conf_wrong": float(conf[~right].mean()) if (~right).any() else None,
            "auroc": auroc(conf, right), "confident_share": float(hi.mean()),
            "confident_error_rate": float((~right[hi]).mean()) if hi.any() else None,
            "acc_top80": top(0.8), "acc_top50": top(0.5)}


def main(split="test"):
    NF.patch_folders()
    st = NF.frozen(split)                       # test: verifies the freeze record first
    th = thresholds(st)
    sg = S.load_groups(split)
    exclude = S.excluded_units()
    ref = json.load(open(f"results/main_v04/noise_{split}.json"))["parts"]
    q_items, label_right, checks = {}, {}, {}
    for v in LEVELS:
        rows = [r for r in D.load_rows(f"{split}_{v}")
                if r["part"] in NF.PARTS and r.get("subset") is None and r["unit"] not in exclude]
        ctx = C.Context(f"{split}_{v}")
        lab = {}
        for r in rows:
            if r["part"] != "r_hear":
                continue
            for p in r["points"]:
                if p["gold"].get("R") is None:
                    continue
                t = p["t"]
                real = any(c in RING for c, _, _ in D.window_events(r, t))
                det = any(s[0] in RING and s[3] >= 0.5 and s[2] > t - D.WIN_S and s[1] < t
                          for s in ctx.point(r, p["k"])[3])
                lab[(r["unit"], r["version"], p["k"])] = real == det
        label_right[v] = lab
        for n, f in FILES.items():
            sc = NF.keyed(json.load(open(os.path.join(NF.R, "final", split, "noise", v, f"{f}.json"))))
            if n in ("2d", "L1"):                # check: group accuracy as the registered noise report
                T = S.unit_table(rows, S.decide(sc, *th[n]), sg)
                for part in NF.PARTS:
                    got = float(np.mean([u["right"] for u in T.values() if u["part"] == part and u["subset"] is None]))
                    want = ref["dnoise10"][part][n]["clean" if v == "dclean" else "degraded"] if v != "dnoise5" \
                        else ref["dnoise5"][part][n]["degraded"]
                    checks[f"{v} {part} {n}"] = {"script": got, "noise report": want}
                    if abs(got - want) > 1e-9:
                        raise SystemExit(f"check failed: {v} {part} {n}: {got} vs noise report {want}")
            for r in rows:
                for p in r["points"]:
                    key = (r["unit"], r["version"], p["k"])
                    for q in ("S", "R"):
                        g = p["gold"].get(q)
                        if g is None:
                            continue
                        s = sc[key][q]
                        t_q = th[n][0] if q == "S" else th[n][1]
                        pos = s >= t_q
                        right = pos == (g == ("stop" if q == "S" else "respond"))
                        q_items.setdefault((n, v, r["part"]), []).append(
                            (key, q, confidence(s, t_q), right))
    out = {"split": split, "note": "post hoc, descriptive (evidence-reliability step 0); no criterion",
           "confidence": "distance from the frozen threshold scaled to [0, 1]", "high": HIGH, "check": checks,
           "by_part": {}, "label_right_r_hear": {}}
    for (n, v, part), items in sorted(q_items.items()):
        out["by_part"].setdefault(part, {}).setdefault(n, {})[v] = summary([x[2] for x in items],
                                                                          [x[3] for x in items])
    keep = {k for k, ok in label_right["dclean"].items() if ok and label_right["dnoise10"].get(k)}
    n_r = len(label_right["dclean"])
    out["label_right_r_hear"]["n_questions"] = {"r_hear": n_r, "label right at both levels": len(keep)}
    for n in FILES:
        row = {}
        for v in ("dclean", "dnoise10"):
            items = [x for x in q_items[(n, v, "r_hear")] if x[1] == "R" and x[0] in keep]
            row[v] = {"n": len(items), "accuracy": float(np.mean([x[3] for x in items])),
                      "mean_conf": float(np.mean([x[2] for x in items]))}
        out["label_right_r_hear"][n] = row
    os.makedirs("results/main_v04", exist_ok=True)
    path = f"results/main_v04/step0_confidence_{split}.json"
    json.dump(out, open(path, "w"), indent=1)
    print(f"check: {len(checks)} group accuracies reproduce the noise report")
    for part in NF.PARTS:
        print(f"== {part}: accuracy / mean confidence / AUROC / confident share / confident errors / top-80% acc")
        for n in FILES:
            cells = []
            for v in LEVELS:
                x = out["by_part"][part][n][v]
                cells.append(f"{v}: " + " ".join("n/a" if x[k] is None else f"{x[k]:.3f}" for k in
                                                  ("accuracy", "mean_conf", "auroc", "confident_share",
                                                   "confident_error_rate", "acc_top80")))
            print(f"  {n:8s} " + " | ".join(cells))
    print(f"== R-hear, label right at both levels ({len(keep)} of {n_r} questions): accuracy, mean confidence")
    for n in FILES:
        x = out["label_right_r_hear"][n]
        print(f"  {n:8s} clean {x['dclean']['accuracy']:.3f} {x['dclean']['mean_conf']:.3f} | "
              f"+10 dB {x['dnoise10']['accuracy']:.3f} {x['dnoise10']['mean_conf']:.3f}")
    print("->", path)


if __name__ == "__main__":
    main(sys.argv[1] if len(sys.argv) > 1 else "test")
